def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    counts = {}
    for row in out:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    for color in counts:
        if color == background:
            continue
        points = [(r, c) for r in range(h) for c in range(w) if out[r][c] == color]
        if len(points) < 3:
            continue
        (r0, c0), (r1, c1) = points[-2], points[-1]
        dr, dc = r1-r0, c1-c0
        if dr == 0 and dc == 0:
            continue
        r, c = r1+dr, c1+dc
        while 0 <= r < h and 0 <= c < w and out[r][c] == background:
            out[r][c] = color
            r, c = r+dr, c+dc
    return out
